x_938076_backup_0_backup_scripts.script:
var oldRefQual = "javascript:\"sys_class_nameIN\"+PPMRoleClassMapper.getClasses('project', gs.getUser());";
var gr = new GlideRecord("sys_dictionary");
gr.addQuery("name", "rm_story");
gr.addQuery("element", "project");
gr.query();

if(gr.next() && gr.getValue("reference_qual") == oldRefQual) {
	gr.setValue("use_reference_qualifier", "advanced");
	gr.setValue("reference_qual", "javascript:ScrumSecurityManager.getStoryDotProject(current);");
	if(gr.update())
		gs.info("Reference qualifier modified");
	else 
		gs.info("Failed to modify reference qualifier");
} else 
	gs.info("Didn't find dictionary record for project field of story. Skipping the update.");
